package pe.edu.lab16.inscripciones;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="inscripciones",uniqueConstraints=@UniqueConstraint(columnNames={"id_evento","id_asistente"})) public class Inscripcion{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="id_evento",nullable=false)private Long idEvento;@Column(name="id_asistente",nullable=false)private Long idAsistente;@Column(nullable=false)private LocalDateTime fecha;@Column(nullable=false,length=20)private String estado;public Long getId(){return id;}public void setId(Long v){id=v;}public Long getIdEvento(){return idEvento;}public void setIdEvento(Long v){idEvento=v;}public Long getIdAsistente(){return idAsistente;}public void setIdAsistente(Long v){idAsistente=v;}public LocalDateTime getFecha(){return fecha;}public void setFecha(LocalDateTime v){fecha=v;}public String getEstado(){return estado;}public void setEstado(String v){estado=v;}}
